import{_ as e,a as o}from"./chunks/3e0823f107b8ccf24315.DlOxo-2V.js";import{_ as a,C as l,o as i,c as s,j as r,a as n,E as h,a5 as g}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"未来永续的技能栈（按此顺序学习）","description":"","frontmatter":{"title":"未来永续的技能栈（按此顺序学习）","originalTitle":"The Future-Proof Skill Stack (Learn In This Order)","date":"2024-03-15","originalUrl":"https://thedankoe.com/letters/the-future-proof-skill-stack-learn-in-this-order/","minutes":11,"sourceHash":"4399519f2c8136e7009c0ff6dddc17c0bd278b9e952c31fff8ed892e5e46f80b","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-proof-skill-stack-learn-in-this-order/"}]]},"headers":[],"relativePath":"letters/the-future-proof-skill-stack-learn-in-this-order.md","filePath":"letters/the-future-proof-skill-stack-learn-in-this-order.md"}'),f={name:"letters/the-future-proof-skill-stack-learn-in-this-order.md"};function d(c,p,u,m,_,k){const t=l("ArticleMeta");return i(),s("div",null,[p[0]||(p[0]=r("h1",{id:"未来永续的技能栈-按此顺序学习",tabindex:"-1"},[n("未来永续的技能栈（按此顺序学习） "),r("a",{class:"header-anchor",href:"#未来永续的技能栈-按此顺序学习","aria-label":'Permalink to "未来永续的技能栈（按此顺序学习）"'},"​")],-1)),h(t),p[1]||(p[1]=g('<p><a href="https://www.youtube.com/embed/DPcw7ZA4LJA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>老实说。</p><p>我很担心。</p><p>我深入研究了通用人工智能（AGI）和后劳动工作的兔子洞。</p><p>过去一个月里，有几个问题一直在我脑海中萦绕：</p><ul><li>人类能做什么机器做不到的事情？</li><li>未来的工作会是什么样子？</li><li>在接下来的20年里，哪些工作——如果有的话——会持续存在？</li><li>作为人类，我们能做些什么来确保一个高于平均水平的未来？</li></ul><p>带着这些问题在脑海中盘旋，我找到了一些答案，或许能在你踏入未知领域时带来一些乐观和清晰。</p><p>我想聚焦在许多人担忧的这一点上：</p><p>我们不知道该教孩子什么，因为我们不知道20年后什么才是相关的。</p><p>我也曾为此担忧，直到我在X上看到<a href="https://twitter.com/Devon_Eriksen_/status/1766666283368562883" target="_blank" rel="noreferrer">Devon Erikson的一篇帖子</a>，为这个问题带来了一些启示。</p><p>我一直在狂听他的所有播客，并阅读他的新科幻小说<a href="https://www.amazon.com/Theft-Fire-Orbital-Space-1-ebook/dp/B0CJHQ4LZN/ref=sr_1_1?crid=3C2XAP9DM9A4O&amp;dib=eyJ2IjoiMSJ9.2gMY5kigj67bbl1ijL46pAs9FPPMdUsHbnq_pBHj3GTrsFy-bQG8OIP3aSgSOR96rpiGFXTHxQLtB3QprzS9bEazs4TzU2ObKCwYEYnrl9KQVY32OwHGonpN8fXe-ImCjSWQNHta-bDuzY3ZCeBbviC87FIOI9o5bTHXEHXeBIRI6eKTR_kopf2vTRwaj91lD2xYwc2WdtZmaRYE945BKlzNrZNtcqspdbAMfRAghZc.ij2Gfs-1FqT1jP0nBxJJ8Y2QuSLkN0JNX6uO4RSHaYA&amp;dib_tag=se&amp;keywords=theft+of+fire&amp;qid=1710342205&amp;sprefix=theft+of+fi%2Caps%2C166&amp;sr=8-1" target="_blank" rel="noreferrer">《Theft Of Fire》</a>。他正迅速成为我最喜欢的思想者之一。</p><p>我希望有一天，当我把他的作品都吸收完之后，能在播客上和他进行一场高水平的对话，分享我们世界观之间的相似与不同之处。现在，我是学生。</p><p>回到他的观点：</p><p><strong>只有奴隶才被期望终生只做一件事。</strong></p><p>我们目前的教育体系反映的正是奴隶的教育方式。</p><p>那些都是特定职业技能，比如种麦子、放羊、骑马。</p><p>如今，我们被教导成为有用的工人。我们被教导要服从权威。我们被条件反射式地训练成因惧怕惩罚而追求好成绩。</p><p><strong>一个自由人被期望依照自己的兴趣行动，一生中做很多事情。</strong></p><p>如果你不为自己创造目标，别人就会给你分配一个。</p><p>目标就是一个目的地。大多数人并不选择自己的目标。</p><p>一个目标意味着必须学习知识和技能，以解决阻碍你实现目标的问题。</p><p>如果你不选择自己的目标，你就不能选择自己要学什么、要解决什么问题。你的命运被别人替你决定，因为你所知道的唯一潜力，就是被分配给你的那一个。</p><p><strong>两者的区别在于如何生活、如何思考、如何学习。</strong></p><p>真正的教育——不是我们称之为公立学校的那种“克隆人生产机器”——是一种关于如何生活、如何在不依赖他人的情况下蓬勃发展的导向。</p><p>真正的教育不仅仅教授通过执行特定任务产生结果的职业技能，还教授如何思考、如何学习，从而能够适应任何情况。</p><p><strong>别再担心AI会让哪些职业技能过时了。</strong></p><p>要担心的是：你是否正在训练（或被训练）去做出符合理想未来的决策，是否具备开放的思维和敏锐的洞察力，是否具备自我驱动的能力。</p><p>每个人都是有创造力的。</p><p>创造力是指用你手头拥有的知识和技能去实现任何目标，而不是花哨的艺术或设计。</p><p>换句话说，你需要学会如何设定自我生成的目标，利用互联网、导师，以及你所能接触到的海量信息来自我教育。</p><p>然后，你需要拥抱试错、自我反思、不断实验，来开创属于自己的道路。</p><p>创造力赋予你在生活中为所欲为的力量。</p><p>那些没有意识到这份天赋的人，注定要接受别人分配的任务。</p><h2 id="不可替代的个体" tabindex="-1">不可替代的个体 <a class="header-anchor" href="#不可替代的个体" aria-label="Permalink to &quot;不可替代的个体&quot;">​</a></h2><p><img src="'+e+'" alt=""></p><p>我们不可能知道未来会是什么样子。</p><p>我们所知道的是，<em>一定会</em>有一种生活方式能带来最大的满足感。</p><p>尽管这种理想生活方式的某些方面是独特的——比如你选择追求的兴趣——但美好生活的总体原则是恒定不变的，比如什么能让你作为一个主权个体去追求这些兴趣。</p><p>要弄清这些原则是什么，我们必须看看<em>学校里没有教什么。</em></p><p>如果学校把你训练成一个终生只做一份职业中的一项任务的现代奴隶，那么那些主权个体所被教导的——或自我教导的——知识和技能又是什么？</p><h3 id="_1-未来永续的技能栈" tabindex="-1">1）未来永续的技能栈 <a class="header-anchor" href="#_1-未来永续的技能栈" aria-label="Permalink to &quot;1）未来永续的技能栈&quot;">​</a></h3><p>在Eriksen看来，七门博雅艺术（或称“解放性艺术”，别与正规教育中某个特定院系里、由那些自身尚未获得解放的人所教授的意识形态怪物混为一谈）分别是，引用如下：</p><ul><li><strong>逻辑</strong>：如何从已知事实中推导出真相</li><li><strong>统计</strong>：如何理解数据背后的含义</li><li><strong>修辞</strong>：如何说服他人，以及识破说服手段</li><li><strong>研究</strong>：如何在未知领域收集信息</li><li><strong>（实用）心理学</strong>：如何识别和理解他人的真实动机</li><li><strong>投资</strong>：如何管理和增长现有资产</li><li><strong>能动性</strong>：如何决定要走的道路，并主动采取行动去追求它。</li></ul><p>我建议你在闯入未知领域时，把这些牢记在心。</p><p>如果你为自己准备好一个能永续应对未来的思维方式，那么哪些技术技能在遥远的未来会赚钱或有用都无关紧要，因为你可以根据需要随时调整。</p><p>为了学习这些解放性艺术，以下是我学到的技能：</p><ul><li><strong>营销与销售</strong>——如果你不知道如何吸引和说服别人，你永远得不到你想要的东西，你唯一的选择就是等雇主（或政府）把它给你。（修辞、心理学）</li><li><strong>写作与思考</strong>——用语言表达出你独特心智中的价值的能力。这是让自己出现在他人面前的基础。（逻辑、研究）</li><li><strong>创业</strong>——把自己的未来掌握在自己手中的过程，为生存而狩猎，打造我想在这个世界上看到的产品（并且是别人也在意的产品）。（统计、能动性、投资）</li></ul><p>有人可能会说创业之类的东西不算“技能”，但我认为，任何随着时间推移会变得更高效的思维过程都是一种技能。</p><p>一切都是技能，但大多数人并没有把自己的人生当作一种练习来对待。</p><p>没有人能告诉你他们是如何写作、思考、营销和销售的。他们只能告诉你他们是怎么做的。</p><p>这意味着，要学会这些技能，你必须拥抱一种自我实验的心态。</p><p>你的任务是：</p><ul><li><strong>研究那些已经取得成功的人所用的流程。</strong> 幸运的是，只需简单搜索就能找到这些信息。</li><li><strong>尝试各种技巧。</strong> 实施你所学到的流程，并试图取得成果。</li><li><strong>识别模式与原则。</strong> 记录每种方法之间的相似之处，并加倍投入其中。</li><li><strong>创造属于自己的流程。</strong> 把你所学到的东西，根据你独特的生活方式和处境进行调整。</li><li><strong>通过传承，为真正的教育做出贡献。</strong> 给人们提供学校里教不了的教育，扎根于批判性思维的基础之上。</li></ul><p>以创业为载体，你为真正的教育与主权奠定了场景。</p><p>通过写作和思考，你不断地创造、测试、迭代自己能提供的价值。</p><p>你必须学习实用心理学——营销和销售——以理解自己和顾客的心智。</p><p>然后你去说服，而不是强迫或欺骗，去激发人们关心你所提供的价值。</p><p>正是这些未来永续的技能，促使我创建了<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>和<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a>（写作+营销与产品）。</p><h3 id="_2-技术知识" tabindex="-1">2）技术知识 <a class="header-anchor" href="#_2-技术知识" aria-label="Permalink to &quot;2）技术知识&quot;">​</a></h3><p>有了未来永续的技能栈作为基础，下一步就是用技术技能去适应时代。</p><p>在这场数字文艺复兴中，这意味着：</p><ul><li><strong>社交媒体</strong>——为自己打造一个品牌，作为你创造价值的门面。这是你事业的指挥中心。</li><li><strong>内容</strong>——写作或视频，用来教育、娱乐并激发人们看到你的价值。</li><li><strong>电邮营销</strong>——通过newsletter或邮件序列来滋养你所积累的受众。</li><li><strong>视觉设计</strong>——描绘出你品牌的氛围，激发观众的情绪。</li><li><strong>销售漏斗搭建</strong>——创建落地页、网站，并用其他技术技能（如内容和电邮）为其提供动力。</li></ul><p>随着人工智能撼动整个行业，学习这些技能的门槛必然会发生变化。它们不会很快消失，但由于获取这些技能的难度降低，整体竞争会加剧。只有少数人会去学习上文提到的未来永续的技能，正是那些技能能保障你的未来。</p><p>这些技术技能是你创业事业当下的载体。</p><h3 id="_3-个人兴趣" tabindex="-1">3）个人兴趣 <a class="header-anchor" href="#_3-个人兴趣" aria-label="Permalink to &quot;3）个人兴趣&quot;">​</a></h3><p>现在你要问的问题是：</p><ul><li>我该写些什么？</li><li>我该营销和销售什么？</li><li>我该用什么内容发邮件、做设计，或运用杠杆技术技能？</li></ul><p>那些你忍不住要告诉别人的兴趣。</p><p>那些你无法把自己从中抽离出来的书籍。</p><p>那些充斥在你搜索历史中的想法。</p><p>那些你梦想去建造、却似乎总找不到时间去做的项目。</p><p>你并不是“找到”一个能盈利的细分领域。你是通过说服创造出一个能盈利的细分领域。</p><p>没有人能告诉你该进入哪个细分领域，他们只能告诉你他们自己进入的那个。</p><p>如果你理解了这些未来永续的技能，从而理解了人性，你就会明白，你可以掌控别人对你兴趣的感知。</p><p>兴趣是被生成的。兴趣是被编程的。你对某些具体事物感兴趣，是因为你被养育的方式，以及你所接触过的信息。</p><p>你对它们感兴趣是有原因的。这意味着，通过在社交媒体上精心布置的文字，别人也能对它们<em>产生</em>兴趣。这种事以前也发生在你身上。去刷一刷时间线，告诉我有没有什么东西说服你改变了行为。</p><p>你把时间、注意力和金钱花在自己的兴趣上。这意味着，只要你足够有价值，别人也会把同样的资源花在你身上。</p><p>自由的人不选择细分领域，他们创造细分领域。</p><h2 id="数字文艺复兴" tabindex="-1">数字文艺复兴 <a class="header-anchor" href="#数字文艺复兴" aria-label="Permalink to &quot;数字文艺复兴&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>大多数人从未尝试在任何一项技能上跻身前5%，因为他们没有意识到，那95%正是由那些除了父母或社会要求他们做的事之外，什么努力都不肯付出的人组成的。</p><p>每天30到60分钟，坚持6到12个月，就能让你超越几乎所有人。</p><p>即便如此，对大多数人来说也已经是过分的要求了。</p><p>多亏了正在我们眼前建立起来的去中心化教育体系（社交媒体上的创作者们，教授他们已经取得成果的路径），你可以快速学习相关技能，从而适应不断变化的职业格局。</p><p>在我看来，把自己的未来押注在那些以教书为职业的人所提供的教育上，是很愚蠢的。</p><p>我说的不是通识教育。那种教育有助于让大家达成共识，很有用。我说的是进阶教育——当你站在那个关键节点上，必须选择要投入哪个方向的兴趣时所需要的教育。</p><p>如果目标是掌控自己的未来，那么明智的做法是，避开那些教你如何获得自由、但自己却并不自由的人所提供的教育。</p><p>STEM 教育是有道理的，因为它教授的是硬技能。但要获得自由所需的“文科式”教育，最好是向那些真正做过你想做的事的人学习。</p><p>文章、播客、视频、课程和辅导。</p><p>用它们来研究我们在这封信里讨论过的每一项技能或兴趣。</p><p>没有人会把时间给你。你必须自己去争取。每天留出30到60分钟不受打扰的时间段，养成这个习惯。就像任何新事物一样，一开始会很难。别指望会有别的结果。</p><h3 id="精通的领域" tabindex="-1">精通的领域 <a class="header-anchor" href="#精通的领域" aria-label="Permalink to &quot;精通的领域&quot;">​</a></h3><p>精通，是创造性工作与专业性工作的融合。</p><p>精通无法被“训练”出来，只能通过实践来获得。</p><p>你的成功不是因为你更聪明。</p><p>你的成功不是因为你更努力。</p><p>你的成功，是因为你拥有与该领域高度相关的专业知识，并且拥有一个创造性的载体，能把这些知识传播出去。</p><p>我可以很聪明，智商175，但如果一个复杂代码库里出现了一个bug，光靠聪明能帮我修复吗？我需要对那个代码库了解一大堆非常具体的东西。</p><p>现在，我可以拥有那个领域的专业知识，但如果我不是那个能影响这个代码库发展方向的人，我就不是自由的，我随时可能被取代。</p><p>一个具备高度专业知识的人，很难被取代，但这依然可能发生。而如果那个人真的被取代了，他有没有足够的创造力，让自己的知识重新为自己所用？</p><p>你的精通领域，包含了上面列出的所有技能和兴趣。</p><ul><li><strong>创业是你的载体</strong>——让你完全掌控自己的未来。</li><li><strong>营销和销售是你的信息</strong>——让你能激励人们关心你所做的事。</li><li><strong>写作和思考是你的媒介</strong>——让你能在公众面前传播你的信息。</li><li><strong>技术know-how是“如何做”</strong>——让你能在当前的市场格局中取得成功。</li><li><strong>个人兴趣是“做什么”</strong>——让你有一门手艺，可以把心血都投入进去。</li><li><strong>你理想的未来是“为什么”</strong>——让你去解决一个你自己有切身经验的问题。</li></ul><p>理想的未来，诞生于逆境之中。</p><p>如果你去听那些最成功的创业者们的故事（排除那些“无意识胜任”的案例），你会发现一个共同的主题。</p><p>他们打造产品，通常出于以下三个原因之一：</p><ol><li>为了做出某个能让自己变得更好的东西。</li><li>为了解决自己生活中的一个问题。</li><li>为了打造出他们想在这个世界上看到的东西。</li></ol><p>或者，更好的情况是——三者兼而有之。</p><p>有一个人患有湿疹，试遍了市面上所有能买到的产品，却找不到一款适合自己的。</p><p>他能找到的最好选择，也只是一块无聊、没有香味的肥皂。</p><p>于是，他痴迷于植物学和园艺学。像拼命一样地钻研它——因为这确实关乎他的命——最终打造出一条系列的肥皂，闻起来好、看起来好，而且不会刺激皮肤。</p><p>再举我自己的例子，我曾经在写作质量的稳定性上遇到困难，而这恰恰是驱动我事业的燃料。似乎没人能理解，写作这件事，远比“写字”本身复杂得多。</p><p>由于这是我事业成功的基石，加上我在这个领域积累了大量专业知识，我不断尝试别人的写作流程，直到我能创造出一套真正适合我独特目标的方法。</p><p>这就是<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>（两小时写作者）诞生的原因——我那个极其成功的课程。</p><p>它可能不适合所有人，但对另一些人来说，这门课改变了一切，并塑造了我们今天所知的创作者圈子的很大一部分——包括许多衍生出来的、采用不同方法的产品，你也可以去尝试。</p><p>注意到了吗，上周讲的<a href="/letters/the-value-equation-how-to-become-a-top-1-individual-fast">价值方程</a>在这里发挥了作用。它始于一个问题，揭示一个目标，然后设定出一个可以被创造出来的潜在流程。</p><p>总结一下，科技只会不断向前发展。</p><p>害怕它，是毁掉你未来的绝佳方式。</p><p>明智的做法是去使用它，去拆解它，去理解它。</p><p>让它帮你更快地掌握技能，以破纪录的速度构建你的未来。</p><p>希望你喜欢这封信。</p><p>到目前为止，这是我最喜欢写的几篇之一。</p><p>丹</p><hr><p><a href="/en/letters/the-future-proof-skill-stack-learn-in-this-order">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',124))])}const P=a(f,[["render",d]]);export{w as __pageData,P as default};
